import{_ as r,C as a,o,c as n,j as e,a as s,E as c,a5 as i}from"./chunks/framework.DjDdFq93.js";const b=JSON.parse('{"title":"第 2 章：剧情分支","description":"","frontmatter":{"title":"第 2 章：剧情分支","prev":{"text":"第 1 章：快速存档","link":"/books/the-perfect-run/01"},"next":{"text":"第 3 章：有荣誉的人","link":"/books/the-perfect-run/03"}},"headers":[],"relativePath":"books/the-perfect-run/02.md","filePath":"books/the-perfect-run/02.md"}'),d={name:"books/the-perfect-run/02.md"};function l(f,p,_,h,u,m){const t=a("ReadingTools");return o(),n("div",null,[p[0]||(p[0]=e("h1",{id:"第-2-章-剧情分支",tabindex:"-1"},[s("第 2 章：剧情分支 "),e("a",{class:"header-anchor",href:"#第-2-章-剧情分支","aria-label":'Permalink to "第 2 章：剧情分支"'},"​")],-1)),p[1]||(p[1]=e("p",{class:"book-author"},"The Perfect Run · Maxime J. Durand · 中文译文",-1)),c(t,{id:"the-perfect-run/02",markable:""}),p[2]||(p[2]=i('<div class="chapter-body"><p>瑞恩做科学研究时，一向只穿内裤。</p><p>衣服体现着社会对人类精神的束缚，体现着文明试图把个体塞进模子里的压迫力量。而近乎赤裸的瑞恩，便能重新接通自己的创造力，不再受从众心态约束；那条平角内裤，则代表他对精神稳定尚存的一丝留恋，防止他彻底脱轨。有一回瑞恩全裸着干活，结果就造出了他的兔子毛绒玩偶。</p><p>再说，他的平角内裤穿着舒服又暖和。那是很多年前，莲亲手给他做的。</p><p>瑞恩在市中心附近租了一间旅馆客房，一大早便一边查新罗马的资料，一边改进自己的小玩意儿。前台接待看见快速存档抱着满手武器上楼，投来古怪的一瞥，却没有叫私人安保。戴着面具的陌生人在这座城里算不上稀罕事。</p><p>当然，瑞恩还是抽空黑进了卧室的摄像头，既保护秘密身份，也避免引起恐慌。他的武器库里可有不少不安全的东西。</p><p>瑞恩坐在椅子上，用脚趾敲电脑键盘——这项本领花了他好多次循环才练成——同时双手继续摆弄线圈枪。雇主已经把昨天送货的报酬汇了过来，顺便称赞他抓住了食尸鬼，不过快递员并不怎么在乎。他干这工作，只是找个借口走遍意大利，寻找新的冒险。</p><p>不过，一听说莲可能在新罗马，他便暂停了无休止的漂泊。</p><p>按雷内斯科的说法，他应该去铁锈镇打听消息；当地迪纳网的资料显示，那是新罗马西北贫民区的外号。控制这座城的公司把所有工厂都塞在那儿，整片地方成了垃圾堆。他们甚至筑起一道墙，防止流浪汉跑到其他城区。</p><p>据前台接待说，“垃圾场”是那一带的地标，由一座旧煤矿改成露天填埋场。许多不受管束的天才和冒险者都在那里交换东西。也许莲就在他们中间。</p><p>有人敲了敲他卧室的窗户。</p><p>瑞恩瞥过去，一个女人正在玻璃另一边向他招手。“嗨。”她说，“能聊一分钟吗？”</p><p>瑞恩的房间在十楼，而且没有消防出口。</p><p>“喂！”瑞恩抓起面具戴好，又扣上帽子。“你侵犯了我的秘密身份！”</p><p>“你根本没有秘密身份，瑞恩·罗马诺。”女人挑起眉毛，“而且按你的档案，你从来就没做过任何掩饰。”</p><p>“我还有档案？”瑞恩喜不自胜。“我出名了！上面怎么形容我？”</p><p>“‘精神错乱，但很可靠。’”太棒了！他们说对了一半！会飞的女人隔着玻璃，从头到脚打量他。“你不打算把其他衣服也穿上吗？”</p><p>瑞恩嘿嘿一笑。“不。”</p><p>他永远反抗压迫者。</p><p>这位私人空间入侵者皱起眉，又敲了敲窗户，比刚才多了几分不耐烦。“你能不能……”</p><p>瑞恩从椅子上起身，一只手开窗，另一只手仍把线圈枪对准来客。</p><p>这回看清了，瑞恩立刻认出了这个女人；昨天他才在广告牌上见过她。她两手叉腰，靠背后高速振动的半透明蜻蜓翅膀悬浮在空中，姿态优雅得如同仙子，尤其是她悬停时完全没有昆虫那样的嗡嗡声。</p><p>“我是飞龙。”这个爱显摆的女人自我介绍道。她穿着无袖的白色紧身制服，左侧是迪纳米斯的 D 形标志，右侧是一颗被金色月桂环绕的银星。她大概二十五到三十出头，十分惹眼。“我想为你昨天抓住食尸鬼的事道声谢。”</p><p>“哦，不客气。”</p><p>接着，瑞恩就开始关窗。</p><p>“喂，等等！”飞龙抓住窗户，不让它合上。瑞恩听说她即使只做部分变身，也能把一辆校车当杠铃卧推，便没有坚持。“你来这座城做什么，快速存档？我可以叫你快速存档吗？”</p><p>“当然。”瑞恩耸耸肩。“我是快递员，负责送信。不管有多少人想让我死！”</p><p>“所以奥古斯都会不是雇你来当打手的？”女超级英雄被他最后那句话逗得有些想笑。“你保护的地方是他们的一处掩护据点。我还以为他们雇你抵挡超能帮，保住地盘呢。”</p><p>“不是。我揍那个老年灾难，只是因为他挡着我完成支线任务。”飞龙露出古怪的表情，听不懂他的行话。基因者战争几乎毁掉了整个电子游戏行业，让瑞恩觉得自己格外孤独。“哦，对了，你听说过一个和我差不多年纪、叫莲的女孩吗？黑头发，蓝眼睛，马克思列宁主义者？”</p><p>“马克思列宁主义者？”飞龙眉头皱得更紧了。“你是说共产主义者？现在还有这种人？”</p><p>“我知道，在这座资本主义横行无忌的城市里，那大概算脏话，不过没错。”</p><p>“没有，我没听说过她。”女超级英雄摇摇头。“但我可以查查我们的档案。你就是为了这个来新罗马的？找她？”</p><p>“哦，是啊，她又漂亮又善良，还是我最好的朋友！”瑞恩忍不住滔滔不绝地夸起她。“我找她都找了不知道多久了！”</p><p>“能帮上的话，我会帮忙。”飞龙微笑着回答。“实际上，我觉得我能帮你很多。”</p><p>哦。</p><p>招揽的话来了……</p><p>“我属于一个叫‘卓越者’的组织。”飞龙说道，印证了瑞恩的猜测。“你大概听说过我们。”</p><p>卓越者。一群企业超级英雄，新罗马的官方守护者，也是当代名流。当然，他们也领着迪纳米斯的工资；公司拥有他们的肖像权、商品开发权，还规定他们该打谁。和利奥·哈格里夫斯的“嘉年华”完全不是一回事。</p><p>那才是真正无偿行侠仗义的超级英雄，游侠骑士那一类！瑞恩总忍不住钦佩他们，尽管正是他们造成了他人生中最糟糕的一天。</p><p>“我们一直在寻找新人才。虽然你在……造成附带损失这方面……颇有名声，但你的超能力极有用处，而且据我们了解，你没涉足过什么不光彩的营生，也没和通缉犯来往密切。”可怜的姑娘，她要是知道就好了。“你在食尸鬼大开杀戒前阻止了他，所以我觉得你的出发点是好的。”</p><p>“所以呢，你想让我去试镜拍电影还是什么？因为我只试过一次演戏，一点都不好玩。”</p><p>飞龙笑了。“我也希望我们少拍点广告，多抓点人。”她承认道。瑞恩听出她的语气里带着一丝苦涩。“但我们确实在尽力保护市民。来我们总部看看，瞧瞧你是否适合我们的组织。你这么收拾了食尸鬼，接下来会需要有人撑腰。”</p><p>“我能照顾自己，谢谢。”瑞恩答道。她觉得他需要被人呵护，这让他有点受辱。</p><p>“听着，快速存档，超能帮可不像奥古斯都会那样讲道理。”她坚持说，“他们是一群四处流窜的疯魔，而你揍了他们的人。他们的老大亚当，是吃人的。”</p><p>“那他肯定忙得吃不消！”</p><p>飞龙不喜欢这个笑话，笑容变得勉强，翅膀也慢下来了一点。</p><p>“好啦，好啦。”瑞恩说，“要是哪天做主线任务时走岔了，我会考虑的。”</p><p>女超级英雄忽然皱眉，朝旁边看了一眼。瑞恩这才注意到她左耳里塞着耳机，不过他什么也听不见。</p><p>“明白。”飞龙说道，却不是对瑞恩说的。随后，她递给快递员一张名片。“如果改变主意，就到这个地址找我们。”</p><p>“行。”</p><p>“保重。”</p><p>说完，飞龙飞走了。她的翅膀振动得太快，人眼已经无法看清，却仍然没有声音，除了翅膀带起的风声。她朝北飞去，转眼间便消失不见，不断加速，直到速度接近超音速。</p><p>她翅膀发声的频率一定超出了人类的听觉范围，或者根本遵循另一套物理规律；放在基因者身上，什么都有可能。快递员记下这个观察，留待以后使用。</p><p>终于只剩自己，瑞恩关好窗，回去继续干活。可他刚坐回椅子，电脑就收到一个语音通话请求。这位基因者立刻认出，呼叫者正是雇他给雷内斯科送货的人。</p><p>他懒洋洋地用左脚脚趾接通语音。“快速存档快递，有什么能为您效劳？”</p><p>“那个婊子跟你说了什么？”另一头传来一个经过加密处理的声音。</p><p>瑞恩在面具后挑起眉。“等等，有人在监视我？”</p><p>“新罗马没多少地方能避开耳目。”</p><p>记着：下个循环找家更隐蔽的旅馆。“我敢肯定，上一个说这话的人没给自己的声音加密。你是谁，阴森森的神秘声音？”</p><p>“我叫伏尔甘。”对方答道。“我代表奥古斯都会。新罗马，以及意大利大部分地区的事，都由我们这个组织说了算。”</p><p>“我还以为是迪纳米斯呢？”瑞恩面无表情地说。</p><p>“他们是这么说的。”那个声音笑了。“但意大利只有一个皇帝，他叫奥古斯都。”</p><p>这话很难反驳。那家伙刀枪不入，还能发射追踪闪电。死在他手里的人，比死于香烟的还多。</p><p>“谢谢你从超能帮那个人渣手里救下我们的员工。”伏尔甘说，“说到底，不管那只带翅膀的蜥蜴许了你什么，我们都能给得更多。”</p><p>“这是个‘无法拒绝的条件’，还是真正的邀请？因为我对马过敏。”</p><p>“我们需要能办成事的狠角色。”伏尔甘答道。“你想要女人，还是男孩？新装备，好武器？多到能让你嗨上月球的极乐？这些玩意儿全都可以是你的……只要你证明自己懂得团队合作。”</p><p>“要怎么证明？”</p><p>一条邮件提醒弹了出来，附着一个地址。瑞恩飞快地查了查，那地方是一家名叫“博徒”的赌场。“那是我们的产业。”伏尔甘解释，“今晚来，一个人，别让我们等。我们从不邀请第二次。”</p><p>瑞恩挂断通话，琢磨这两份邀请。呼，才揍了一个人——按他平常的标准，已经极其克制、极其温柔——突然间，所有人都想来分他一块。</p><p>不过话说回来，无论哪一方，都有可能帮他找到莲，而他进城前已经设好了存档点。</p><p>那就只意味着一件事。</p><p>“多条路线已解锁！”</p></div><hr><p><a href="https://www.royalroad.com/fiction/36735/the-perfect-run/chapter/569531/2-story-branching" target="_blank" rel="noreferrer">原文入口</a> · <a href="/books/the-perfect-run/">返回作品目录</a></p>',3))])}const T=r(d,[["render",l]]);export{b as __pageData,T as default};
